CREATE FUNCTION public.portfolio_permissoes() RETURNS TABLE(fonte_tipo text,fonte_id uuid) LANGUAGE sql STABLE SET search_path=public AS $$ SELECT 'projeto'::text,p.id FROM public.projetos p WHERE public.portfolio_pode_editar('projeto',p.id) UNION ALL SELECT 'iniciativa'::text,i.id FROM public.mt_iniciativas i WHERE public.portfolio_pode_editar('iniciativa',i.id) $$;
REVOKE ALL ON FUNCTION public.portfolio_permissoes() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.portfolio_permissoes() TO authenticated;
CREATE FUNCTION public.portfolio_iniciar_job(_tipo text,_id uuid,_usuario uuid,_novo boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j portfolio_vinculacao_jobs%ROWTYPE; BEGIN INSERT INTO portfolio_vinculacao_jobs(fonte_tipo,fonte_id,criado_por) VALUES(_tipo,_id,_usuario) ON CONFLICT DO NOTHING; SELECT * INTO j FROM portfolio_vinculacao_jobs WHERE fonte_tipo=_tipo AND fonte_id=_id FOR UPDATE; IF j.status='executando' OR j.status='pausado' OR (_novo AND (j.status<>'pendente' OR j.criado_por IS DISTINCT FROM _usuario)) THEN RAISE EXCEPTION 'Item já processado ou pausado.'; END IF; UPDATE portfolio_vinculacao_jobs SET status='executando',criado_por=_usuario,updated_at=now() WHERE id=j.id; RETURN j.id; END $$;
REVOKE ALL ON FUNCTION public.portfolio_iniciar_job(text,uuid,uuid,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.portfolio_iniciar_job(text,uuid,uuid,boolean) TO service_role;
CREATE FUNCTION public.portfolio_retomar_ia() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT coalesce(public.proj_gov_ou_ceo(auth.uid()),false) THEN RAISE EXCEPTION 'Somente Governança e CEO.'; END IF; IF EXISTS(SELECT 1 FROM portfolio_vinculacao_jobs WHERE bloqueio='provider_denied') THEN RAISE EXCEPTION 'Acesso ao provedor precisa ser restabelecido antes da retomada.'; END IF; UPDATE portfolio_vinculacao_jobs SET status='erro',bloqueio=NULL,updated_at=now() WHERE status='pausado' AND bloqueio IN('credit_pause','workspace_pause'); END $$;
REVOKE ALL ON FUNCTION public.portfolio_retomar_ia() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.portfolio_retomar_ia() TO authenticated;
-- Compatibility writes to the legacy link tables mirror into proposals, without reviving removed pairs or replacing validated links.
CREATE FUNCTION public.portfolio_espelhar_legado() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ft text; fid uuid; t text; BEGIN ft:=CASE WHEN TG_TABLE_NAME='projeto_vinculos' THEN 'projeto' ELSE 'iniciativa' END; fid:=CASE WHEN ft='projeto' THEN (to_jsonb(NEW)->>'projeto_id')::uuid ELSE (to_jsonb(NEW)->>'iniciativa_id')::uuid END; IF NEW.tipo='projeto' THEN RETURN NEW; END IF; t:=CASE WHEN NEW.tipo IN('bsc_objetivo','objetivo') THEN 'objetivo' ELSE 'indicador' END; IF public.estrategia_alvo_ativo(t,NEW.ref_id) AND NOT EXISTS(SELECT 1 FROM portfolio_vinculos WHERE fonte_tipo=ft AND fonte_id=fid AND status='validado') THEN INSERT INTO portfolio_vinculos(fonte_tipo,fonte_id,tipo,ref_id,origem,justificativa,proposto_por) VALUES(ft,fid,t,NEW.ref_id,'legado','Vínculo informado no cadastro de origem',auth.uid()) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER portfolio_legado AFTER INSERT ON public.projeto_vinculos FOR EACH ROW EXECUTE FUNCTION public.portfolio_espelhar_legado();
CREATE TRIGGER portfolio_legado AFTER INSERT ON public.mt_acao_vinculos FOR EACH ROW EXECUTE FUNCTION public.portfolio_espelhar_legado();